.Zone2DelayGround} cycles for ground faults (Z2DG). {supervision} {note}","settings":[{"code":"Z2%","exprText":"input.Zone2Pct","expr":{"fact":"input.Zone2Pct"}},{"code":"Z2DP","exprText":"input.Zone2DelayPhase","expr":{"fact":"input.Zone2DelayPhase"}},{"code":"Z2DG","exprText":"input.Zone2DelayGround","expr":{"fact":"input.Zone2DelayGround"}}],"values":[]},{"key":"Z3","kind":"element","title":"Zone 3","statement":"Set zone 3 to {input.Zone3Pct}% of the distance to {line.RemoteStation}, time delayed {input.Zone3Delay} cycles (Z3D). {supervision} {note}","settings":[{"code":"Z3%","exprText":"input.Zone3Pct","expr":{"fact":"input.Zone3Pct"}},{"code":"Z3D","exprText":"input.Zone3Delay","expr":{"fact":"input.Zone3Delay"}}],"values":[]},{"key":"50P","kind":"element","title":"Supervisory phase overcurrent (50P)","statement":"The supervisory overcurrents must be set high enough not to pick up on the line charging current: I charge = {value.ChargingMva} MVA/mile × {line.LengthMiles} miles × {value.AmpsPerMva} A/MVA = {value.ChargingA} A primary. Set 50P = {setting.50P} A. {note}","settings":[{"code":"50P","exprText":"input.Pickup50P","expr":{"fact":"input.Pickup50P"}}],"values":[{"name":"ChargingMva","exprText":"coalesce(line.ChargingMvaPerMile, input.ChargingMvaPerMile)","expr":{"fn":"coalesce","a":[{"fact":"line.ChargingMvaPerMile"},{"fact":"input.ChargingMvaPerMile"}]}},{"name":"AmpsPerMva","exprText":"round(1000000 / (1.7320508 * line.kV * 1000), 2)","expr":{"fn":"round","a":[{"op":"/","l":{"lit":"1000000","t":"num"},"r":{"op":"*","l":{"op":"*","l":{"lit":"1.7320508","t":"num"},"r":{"fact":"line.kV"}},"r":{"lit":"1000","t":"num"}}},{"lit":"2","t":"num"}]}},{"name":"ChargingA","exprText":"round(coalesce(line.ChargingMvaPerMile, input.ChargingMvaPerMile) * line.LengthMiles * (1000000 / (1.7320508 * line.kV * 1000)), 2)","expr":{"fn":"round","a":[{"op":"*","l":{"op":"*","l":{"fn":"coalesce","a":[{"fact":"line.ChargingMvaPerMile"},{"fact":"input.ChargingMvaPerMile"}]},"r":{"fact":"line.LengthMiles"}},"r":{"op":"/","l":{"lit":"1000000","t":"num"},"r":{"op":"*","l":{"op":"*","l":{"lit":"1.7320508","t":"num"},"r":{"fact":"line.kV"}},"r":{"lit":"1000","t":"num"}}}},{"lit":"2","t":"num"}]}}]},{"key":"50NG","kind":"element","title":"Supervisory residual overcurrent (50NG)","statement":"Set 50NG = {setting.50NG} A, above the charging current ({value.ChargingA} A) and below the line-ground fault level at the far end. {note}","settings":[{"code":"50NG","exprText":"input.Pickup50NG","expr":{"fact":"input.Pickup50NG"}}],"values":[{"name":"ChargingA","exprText":"value.ChargingA","expr":{"fact":"value.ChargingA"}}]},{"key":"50H","kind":"element","title":"High-set phase overcurrent (50H, switch-onto-fault)","statement":"The close-in three-phase fault level is {input.CloseInFaultA} A primary; the high-set overcurrent trips through the MTO mask while 52BT is asserted after the breaker closes, so that a line energized onto ground leads trips back out at once. Set 50H = {setting.50H} A. {supervision} {note}","settings":[{"code":"50H","exprText":"coalesce(input.Pickup50H, round(0.5 * input.CloseInFaultA, 0))","expr":{"fn":"coalesce","a":[{"fact":"input.Pickup50H"},{"fn":"round","a":[{"op":"*","l":{"lit":"0.5","t":"num"},"r":{"fact":"input.CloseInFaultA"}},{"lit":"0","t":"num"}]}]}}],"values":[]},{"key":"51N","kind":"element","title":"Residual time-overcurrent (51N)","statement":"The inverse-time residual element picks up at {setting.51NP} A on curve {setting.51NC} with time dial {setting.51NTD}; torque control {setting.51NTC}. {supervision} {note}","settings":[{"code":"51NP","exprText":"input.Pickup51NP","expr":{"fact":"input.Pickup51NP"}},{"code":"51NC","exprText":"input.Curve51NC","expr":{"fact":"input.Curve51NC"}},{"code":"51NTD","exprText":"input.TimeDial51NTD","expr":{"fact":"input.TimeDial51NTD"}},{"code":"51NTC","exprText":"input.TorqueControl51NTC","expr":{"fact":"input.TorqueControl51NTC"}}],"values":[]},{"key":"67N","kind":"element","title":"Residual instantaneous overcurrent (67N)","statement":"The line-ground fault at {line.RemoteStation} is {input.RemoteFaultA} A at maximum generation; the instantaneous unit is set at 150% of it: 67NP = {setting.67NP} A, torque control {setting.67NTC}. {supervision} {note}","settings":[{"code":"67NP","exprText":"coalesce(input.Pickup67NP, round(1.5 * input.RemoteFaultA, 0))","expr":{"fn":"coalesce","a":[{"fact":"input.Pickup67NP"},{"fn":"round","a":[{"op":"*","l":{"lit":"1.5","t":"num"},"r":{"fact":"input.RemoteFaultA"}},{"lit":"0","t":"num"}]}]}},{"code":"67NTC","exprText":"input.TorqueControl67NTC","expr":{"fact":"input.TorqueControl67NTC"}}],"values":[]},{"key":"32Q","kind":"element","title":"Negative-sequence directional element (32Q)","statement":"The negative-sequence directional element, adjusted by the maximum torque angle MTA = {setting.MTA}°, always supervises the distance elements and, with torque control set, the residual overcurrent elements (2-24). {note}","settings":[],"values":[]},{"key":"LOP","kind":"element","title":"Loss-of-potential detection (LOP)","statement":"Enable the loss-of-potential logic: LOPE = {setting.LOPE}; on loss of potential the distance elements are blocked (2-18). {note}","settings":[{"code":"LOPE","exprText":"input.Lope","expr":{"fact":"input.Lope"}}],"values":[]},{"key":"79","kind":"element","title":"Reclosing (79)","statement":"Reclosing is initiated by the elements marked so below: open interval 79OI = {setting.79OI} cycles, reset time 79RS = {setting.79RS} cycles. {note}","settings":[{"code":"79OI","exprText":"input.OpenInterval","expr":{"fact":"input.OpenInterval"}},{"code":"79RS","exprText":"input.ResetTime","expr":{"fact":"input.ResetTime"}}],"values":[]},{"key":"25","kind":"element","title":"Synchronism and voltage checking (25, 27, 59)","statement":"PSVC = {setting.PSVC}; dead below 27VLO = {setting.27VLO}, live above 59VHI = {setting.59VHI}; difference voltage 25DV = {setting.25DV}; sync check on phase {setting.SYNCP}; in phase for 25T = {setting.25T} cycles; voltages constant for VCT = {setting.VCT} cycles. {note}","settings":[{"code":"PSVC","exprText":"input.Psvc","expr":{"fact":"input.Psvc"}},{"code":"27VLO","exprText":"input.VoltsLow","expr":{"fact":"input.VoltsLow"}},{"code":"59VHI","exprText":"input.VoltsHigh","expr":{"fact":"input.VoltsHigh"}},{"code":"25DV","exprText":"input.DiffVolts","expr":{"fact":"input.DiffVolts"}},{"code":"SYNCP","exprText":"input.SyncPhase","expr":{"fact":"input.SyncPhase"}},{"code":"25T","exprText":"input.SyncTimer","expr":{"fact":"input.SyncTimer"}},{"code":"VCT","exprText":"input.VoltageTimer","expr":{"fact":"input.VoltageTimer"}}],"values":[]},{"key":"REJO","kind":"element","title":"Remote-end-just-opened (REJO)","statement":"Remote-end-just-opened tripping: REJOE = {setting.REJOE}. {note}","settings":[{"code":"REJOE","exprText":"input.Rejoe","expr":{"fact":"input.Rejoe"}}],"values":[]},{"key":"SOTF","kind":"element","title":"Switch-onto-fault (52BT)","statement":"Set 52BT = {setting.52BT} cycles, which enables the switch-onto-fault protection (the MTO mask) for that long after the breaker is closed. {note}","settings":[{"code":"52BT","exprText":"input.Bt52","expr":{"fact":"input.Bt52"}}],"values":[]},{"key":"FAULTLOC","kind":"element","title":"Fault locating","statement":"The fault locator uses the line data above; line length LL = {setting.LL} miles. {note}","settings":[{"code":"LL","exprText":"line.LengthMiles","expr":{"fact":"line.LengthMiles"}}],"values":[]},{"key":"TIMERS","kind":"group","title":"Timers","statement":"A1TP = {setting.A1TP}, A1TD = {setting.A1TD}; minimum trip duration TDUR = {setting.TDUR} cycles. {note}","settings":[{"code":"A1TP","exprText":"input.A1Pickup","expr":{"fact":"input.A1Pickup"}},{"code":"A1TD","exprText":"input.A1Dropout","expr":{"fact":"input.A1Dropout"}},{"code":"TDUR","exprText":"input.TripDuration","expr":{"fact":"input.TripDuration"}}],"values":[]},{"key":"COMMS","kind":"group","title":"Communications","statement":"TIME1 = {setting.TIME1}, TIME2 = {setting.TIME2}, AUTO = {setting.AUTO}, RINGS = {setting.RINGS}. {note}","settings":[{"code":"TIME1","exprText":"input.Time1","expr":{"fact":"input.Time1"}},{"code":"TIME2","exprText":"input.Time2","expr":{"fact":"input.Time2"}},{"code":"AUTO","exprText":"input.Auto","expr":{"fact":"input.Auto"}},{"code":"RINGS","exprText":"input.Rings","expr":{"fact":"input.Rings"}}],"values":[]},{"key":"MASKS","kind":"group","title":"Logic masks","statement":"MTU, MRI and MTO follow the elements above (the trip, reclose-initiate and trip-with-breaker-open marks); the other masks as set here. {note}","settings":[{"code":"MPT","exprText":"input.MaskMPT","expr":{"fact":"input.MaskMPT"}},{"code":"MTB","exprText":"input.MaskMTB","expr":{"fact":"input.MaskMTB"}},{"code":"MA1","exprText":"input.MaskMA1","expr":{"fact":"input.MaskMA1"}},{"code":"MA2","exprText":"input.MaskMA2","expr":{"fact":"input.MaskMA2"}},{"code":"MA3","exprText":"input.MaskMA3","expr":{"fact":"input.MaskMA3"}},{"code":"MA4","exprText":"input.MaskMA4","expr":{"fact":"input.MaskMA4"}},{"code":"MRC","exprText":"input.MaskMRC","expr":{"fact":"input.MaskMRC"}}],"values":[]}],"derivedMasks":{"MTU":{"input":"Trips","outputs":{"Z1":["Z1P","Z1G"],"Z2":["Z2PT","Z2GT"],"Z3":["Z3T"],"51N":["51NT"],"67N":["67N"]}},"MRI":{"input":"Recloses","outputs":{"Z1":["Z1P","Z1G"],"Z2":["Z2PT","Z2GT"],"Z3":["Z3T"],"51N":["51NT"],"67N":["67N"]}},"MTO":{"input":"Trips","outputs":{"50H":["50H"]}}}}';
DECLARE @note NVARCHAR(200) = N'seed 07792cdc87881ec7';
SELECT @e = EntityId FROM [config].[Definition] WHERE [DefinitionKind] = N'Program.Rationale' AND [DefinitionKey] = N'RATIONALE_SEL221F_LINE' AND [IsDeleted] = 0;
IF @e IS NULL
    EXEC [config].[AddDefinition] @DefinitionKind = N'Program.Rationale', @DefinitionKey = N'RATIONALE_SEL221F_LINE', @Name = N'SEL-221F line distance protection rationale',
         @Description = N'The settings rationale of an SEL-221F on a transmission line: one section per protective element, the inputs the engineer answers, the formulas that make the settings values, the statements the document is assembled from (#219).', @ActorId = @author, @EntityId = @e OUTPUT;
IF NOT EXISTS (SELECT 1 FROM [config].[vDefinitionVersion] WHERE [DefinitionEntityId] = @e AND [ChangeNote] NOT LIKE N'seed %')      -- untouched by an Administrator
   AND NOT EXISTS (SELECT 1 FROM [config].[vDefinitionVersion] WHERE [DefinitionEntityId] = @e AND [Status] = N'Effective' AND [ChangeNote] = @note)
BEGIN
    EXEC [config].[AddDefinitionVersion] @DefinitionKey = N'RATIONALE_SEL221F_LINE', @DefinitionKind = N'Program.Rationale', @ChangeNote = @note, @PayloadText = @payload, @ActorId = @author, @VersionRowId = @v OUTPUT, @VersionNumber = @no OUTPUT;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Line', @Name = N'The line', @DataType = N'Reference', @UnitCode = NULL, @DisplayGroup = N'LINE', @DisplayOrder = 1, @ReferenceTargetKind = N'Asset', @Description = N'The transmission line this relay protects; prefilled from the scheme that names the relay and the line it protects, else picked here.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_LINE', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'LINE', @DisplayOrder = 2, @Description = N'Your own words on the line data, appended to the section.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'CtPrimary', @Name = N'CT ratio, primary', @DataType = N'Decimal', @UnitCode = N'A', @DisplayGroup = N'INPUTS', @DisplayOrder = 3, @Description = N'The current transformer ratio''s primary amperes (A4811: ''CT Ratio=800-5''; A0394: 600-5).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'CtSecondary', @Name = N'CT ratio, secondary', @DataType = N'Decimal', @UnitCode = N'A', @DisplayGroup = N'INPUTS', @DisplayOrder = 4, @Description = N'The current transformer ratio''s secondary amperes.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'PtPrimary', @Name = N'PT ratio, primary', @DataType = N'Decimal', @UnitCode = NULL, @DisplayGroup = N'INPUTS', @DisplayOrder = 5, @Description = N'The potential transformer ratio (A4811: ''PT Ratio=1200-1''; A0394: 600-1). Ratio to 1.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'SptPrimary', @Name = N'Synchronizing PT ratio', @DataType = N'Decimal', @UnitCode = NULL, @DisplayGroup = N'INPUTS', @DisplayOrder = 6, @Description = N'The synchronizing potential transformer ratio to 1 (A4811: ''Set SPTR=700 - The sync pt is set on its 115 volt winding''; A0394: 350).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_INPUTS', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'INPUTS', @DisplayOrder = 7, @Description = N'Your own words on the instrument transformers.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'FaultStudyDate', @Name = N'Fault study date', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'FAULTSTUDY', @DisplayOrder = 8, @Description = N'When the fault study was run (A4811: November 22, 2023).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_FAULTSTUDY', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'FAULTSTUDY', @DisplayOrder = 9, @Description = N'Your own words on the fault study.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Used_Z1', @Name = N'Zone 1 in use', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z1', @DisplayOrder = 10, @Description = N'Whether zone 1 is used at this position.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Zone1Pct', @Name = N'Zone 1 reach, % of the line', @DataType = N'Decimal', @UnitCode = N'%', @DisplayGroup = N'Z1', @DisplayOrder = 11, @Description = N'A4811: ''Set zone 1 at 85% of the distance to St. Andre.''; A0394: 85% to the low-voltage bus, adjusted to 80%.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Trips_Z1', @Name = N'Zone 1 trips (MTU)', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z1', @DisplayOrder = 12, @Description = N'Zone 1 phase and ground (Z1P, Z1G) in the unconditional trip mask (A4811 and A0394: yes).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Recloses_Z1', @Name = N'Zone 1 initiates reclosing (MRI)', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z1', @DisplayOrder = 13, @Description = N'Z1P, Z1G in the reclose initiate mask (A4811: ''Line reclosing will be initiated by any trip coming from the protection'').', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_Z1', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'Z1', @DisplayOrder = 14, @Description = N'Your own words on zone 1 (A0394 explains a tap: ''Setting=26.03/(36.07*cos(90-64.55))*100%=80%'').', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Used_Z2', @Name = N'Zone 2 in use', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z2', @DisplayOrder = 15, @Description = N'Zone 2 in use', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Zone2Pct', @Name = N'Zone 2 reach, % of the line', @DataType = N'Decimal', @UnitCode = N'%', @DisplayGroup = N'Z2', @DisplayOrder = 16, @Description = N'A4811: ''Set zone 2 to 130% of the distance to St. Andre''; A0394: 100% to the normally open point.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Zone2DelayPhase', @Name = N'Zone 2 delay, phase (Z2DP)', @DataType = N'Decimal', @UnitCode = N'cycles', @DisplayGroup = N'Z2', @DisplayOrder = 17, @Description = N'A4811: ''Use a time delay of 18 cycles (0.3 seconds)''; A0394: 90 cycles to coordinate with fuses.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Zone2DelayGround', @Name = N'Zone 2 delay, ground (Z2DG)', @DataType = N'Decimal', @UnitCode = N'cycles', @DisplayGroup = N'Z2', @DisplayOrder = 18, @Description = N'A4811: 18; A0394: 18 (''the ground distance elements can trip much faster'').', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Trips_Z2', @Name = N'Zone 2 trips (MTU)', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z2', @DisplayOrder = 19, @Description = N'Z2PT, Z2GT in the unconditional trip mask.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Recloses_Z2', @Name = N'Zone 2 initiates reclosing (MRI)', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z2', @DisplayOrder = 20, @Description = N'Zone 2 initiates reclosing (MRI)', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_Z2', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'Z2', @DisplayOrder = 21, @Description = N'Note', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Used_Z3', @Name = N'Zone 3 in use', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z3', @DisplayOrder = 22, @Description = N'Zone 3 in use', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Zone3Pct', @Name = N'Zone 3 reach, % of the line', @DataType = N'Decimal', @UnitCode = N'%', @DisplayGroup = N'Z3', @DisplayOrder = 23, @Description = N'A0394: ''Set zone 3 at 130% of the distance to the normally open point''; A4811: 1314% for an abnormal condition, ''normally turned off in the MTU mask''.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Zone3Delay', @Name = N'Zone 3 delay (Z3D)', @DataType = N'Decimal', @UnitCode = N'cycles', @DisplayGroup = N'Z3', @DisplayOrder = 24, @Description = N'A4811: Z3D=36; A0394: 156 (2.6 seconds).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Trips_Z3', @Name = N'Zone 3 time-delayed trips (MTU)', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z3', @DisplayOrder = 25, @Description = N'Z3T in the unconditional trip mask (A0394: yes; A4811: normally off).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Recloses_Z3', @Name = N'Zone 3 initiates reclosing (MRI)', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'Z3', @DisplayOrder = 26, @Description = N'Zone 3 initiates reclosing (MRI)', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_Z3', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'Z3', @DisplayOrder = 27, @Description = N'Note', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Used_50P', @Name = N'50P in use', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'50P', @DisplayOrder = 28, @Description = N'50P in use', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'ChargingMvaPerMile', @Name = N'Line charging, MVA per mile', @DataType = N'Decimal', @UnitCode = NULL, @DisplayGroup = N'50P', @DisplayOrder = 29, @Description = N'Used when the line asset carries none (A4811: ''0.128 MVA/mile'' at 138 kV; A0394: 0.032 at 69 kV).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Pickup50P', @Name = N'50P pickup', @DataType = N'Decimal', @UnitCode = N'A', @DisplayGroup = N'50P', @DisplayOrder = 30, @Description = N'A4811: ''Set 50NG=80 amps and 50P=80 amps''; A0394: 100. Above the charging current, about 1/3 of the far-end fault level.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_50P', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'50P', @DisplayOrder = 31, @Description = N'Note', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Used_50NG', @Name = N'50NG in use', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'50NG', @DisplayOrder = 32, @Description = N'50NG in use', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Pickup50NG', @Name = N'50NG pickup', @DataType = N'Decimal', @UnitCode = N'A', @DisplayGroup = N'50NG', @DisplayOrder = 33, @Description = N'A4811: 80; A0394: 60 (''this will provide good sensitivity for all line faults'').', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_50NG', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'50NG', @DisplayOrder = 34, @Description = N'Note', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Used_50H', @Name = N'50H in use', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'50H', @DisplayOrder = 35, @Description = N'50H in use', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'CloseInFaultA', @Name = N'Close-in three-phase fault, A', @DataType = N'Decimal', @UnitCode = N'A', @DisplayGroup = N'50H', @DisplayOrder = 36, @Description = N'A0394: ''The close in three phase fault level at Eel River is 7000 amps primary''; A4811 did not use it (50H=5000, ''will not be used'').', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Pickup50H', @Name = N'50H pickup (override)', @DataType = N'Decimal', @UnitCode = N'A', @DisplayGroup = N'50H', @DisplayOrder = 37, @Description = N'Leave empty for 50 % of the close-in fault (A0394: ''trip at 50% of the close in fault level ... Set 50H=3500''); or set it.', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Trips_50H', @Name = N'50H trips with the breaker open (MTO)', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'50H', @DisplayOrder = 38, @Description = N'50H in the trip-with-breaker-open mask (A0394: ''MTO Set to trip on high set overcurrent''; A4811: off).', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Note_50H', @Name = N'Note', @DataType = N'Text', @UnitCode = NULL, @DisplayGroup = N'50H', @DisplayOrder = 39, @Description = N'Note', @ActorId = @author;
    EXEC [config].[CharacteristicDefinition_Add] @DefinitionVersionRowId = @v, @CharacteristicKey = N'Used_51N', @Name = N'51N in use', @DataType = N'Boolean', @UnitCode = NULL, @DisplayGroup = N'51N', @DisplayOrder = 40, @Description = N'51N in use', @ActorId = @author;
